import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Set;

public class SecureServer {
    // A whitelist of allowed classes to prevent deserialization attacks
    private static final Set<String> ALLOWED_CLASSES = Set.of("java.lang.String", "java.util.ArrayList");

    // A custom ObjectInputStream that implements look-ahead deserialization
    public static class SafeObjectInputStream extends ObjectInputStream {
        public SafeObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Check if the class being deserialized is in our approved list
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
            }
            return super.resolveClass(desc);
        }
    }

    public static void main(String[] args) throws Exception {
        ServerSocket serverSocket = new ServerSocket(8080);
        System.out.println("Secure server listening on port 8080...");

        while (true) {
            try (Socket clientSocket = serverSocket.accept();
                 SafeObjectInputStream ois = new SafeObjectInputStream(clientSocket.getInputStream())) {

                // FIXED: Use a SafeObjectInputStream to validate classes before instantiation
                Object data = ois.readObject();
                System.out.println("Received object: " + data.toString());
            } catch (Exception e) {
                System.err.println("Blocked a potential attack: " + e.getMessage());
            }
        }
    }
}
